{
  "name": "Regular Medicaid / Aged Blind and Disabled",
  "eligibility": {
    "age": 65,
    "income_limits": {
      "programs": [
        {
          "category": "Medicaid for Older Citizens (MAA)",
          "who": "Age 65 or older",
          "limit": "Income must be below the program limit; the consumer guide points to a separate income table, but the exact dollar table was not included in the gathered excerpts."
        },
        {
          "category": "Medicaid for the Blind or Visually Impaired (MAB)",
          "who": "Blind or visually impaired people of any age who meet the SSA blindness definition",
          "limit": "Income must meet the program limit; the gathered excerpts indicate a limit table exists, but the exact dollar table was not included in the gathered excerpts."
        },
        {
          "category": "Medicaid for Disabled Citizens (MAD)",
          "who": "Any age, if disabled under Medicaid/SSA rules",
          "limit": "Income must meet the program limit; the gathered excerpts indicate a limit table exists, but the exact dollar table was not included in the gathered excerpts."
        }
      ],
      "known_reference_points": [
        "One county DSS page states Aged, Blind and Disabled Medicaid uses an income limit of $1,330 per month for an individual.",
        "A separate DB101 excerpt also states disability-based NC Medicaid uses 100% of the Federal Poverty Guidelines, including $1,330/month for one person and $1,804/month for two people."
      ],
      "household_table": null,
      "note": "North Carolina distinguishes between MAA, MAB, and MAD categories, and the exact income test depends on which category the applicant fits. The official consumer guide referenced a page with the full income table, but those exact figures were not present in the extracted text."
    },
    "asset_limits": {
      "limit": {
        "individual": 2000,
        "couple": 3000
      },
      "what_counts": [
        "Savings in the bank",
        "Other countable resources used in Medicaid resource budgeting"
      ],
      "what_is_exempt": [
        "The excerpts reviewed did not include the full exemption list.",
        "The state policy manual indicates some property can be treated specially; for example, certain real property may be excluded under specific conditions."
      ],
      "notes": [
        "For disability-based NC Medicaid, countable resources must be at or below $2,000 for one person or $3,000 for a couple.",
        "NC policy materials also show that resources are a core test for MAA/MAB/MAD."
      ]
    },
    "other_requirements": [
      "Must meet the Social Security Administration definition of blindness for MAB.",
      "Must meet disability rules for MAD; the consumer guide says the disability must prevent substantial work and be expected to last at least 12 months.",
      "Must be a U.S. citizen or otherwise have an immigration status eligible for NC Medicaid.",
      "Cannot be incarcerated or a resident of a public institution.",
      "SSI recipients who receive SSI because they are disabled are considered to meet the disability requirement.",
      "Some cases require state disability determination paperwork through DDS."
    ]
  },
  "benefits": {
    "type": "service",
    "value": "NC Medicaid coverage for medical care under the aged, blind, and disabled categories. The gathered excerpts specifically mention coverage for long-term services and supports, including help at home, in the community, and in nursing homes. Long-term care coverage can include nursing facility care, personal care assistance, skilled nursing, therapy, and some home health services. No fixed dollar benefit or weekly hour amount was provided in the gathered excerpts. CAP/DA, when eligible, is a separate long-term service pathway that can provide in-home/community supports instead of institutional care.",
    "varies_by": "fixed"
  },
  "application": {
    "methods": [
      "Online at https://epass.nc.gov",
      "Download, print, and mail the application to your local County Department of Social Services",
      "Email, fax, or bring the application to your local DSS office",
      "Phone your local DSS office",
      "In person at your local DSS office"
    ],
    "processing_time": "No exact statewide processing time was included in the gathered excerpts.",
    "waitlist": "No waitlist was identified for Regular Medicaid / Aged Blind and Disabled Medicaid itself. Long-term services through other programs may have separate eligibility or service-delivery constraints, but the gathered excerpts did not show a Medicaid waitlist for this category.",
    "forms": [
      "NC Medicaid application (general application)",
      "DMA-5202D-ia, Income/Resources - Appendix D",
      "Other additional forms may be required depending on the situation"
    ],
    "documents": [
      "Copies of income proof if available",
      "Proof of resources/assets if available",
      "Signed application",
      "Information supporting disability or blindness if not already established through SSA",
      "Immigration/citizenship documents if relevant",
      "Any additional forms requested by DSS"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Statewide in North Carolina, but applications are handled through the county Department of Social Services where the applicant lives.",
    "regional_variations": "Eligibility rules are statewide. Administrative routing is county-based, and county contact numbers, office access, and any local processing speed differences can vary by county. The gathered excerpts did not show a formal regional benefit variation for the regular Aged, Blind, and Disabled Medicaid category.",
    "offices_or_providers": [
      "Local County Department of Social Services offices across North Carolina",
      "North Carolina DSS local office directory",
      "NC DHHS Medicaid application portal"
    ]
  },
  "official_source": "https://medicaid.ncdhhs.gov/apply",
  "gotchas": [
    "People often confuse Regular Medicaid for Aged, Blind and Disabled with long-term-care waivers or nursing-home Medicaid; those can have different rules.",
    "Disability-based Medicaid is not automatic unless the person already receives SSI or SSDI-based disability status that NC accepts in the category.",
    "Income and resource rules are separate; meeting one does not guarantee eligibility.",
    "Spousal resources can matter when spouses live together.",
    "Some property may be treated differently than cash resources, so real estate should not be assumed countable without review.",
    "Applications go through the county DSS, not a single statewide intake office."
  ],
  "data_shape_notes": "This program is category-based, not one uniform benefit. The structure changes by whether the person is aged, blind, or disabled, and the eligibility test uses both income and countable resources, with special handling for disability determinations and county-based administration."
