{
  "name": "Circuit Breaker Property Tax Deferral",
  "eligibility": {
    "age": 65,
    "income_limits": {
      "2026_state_standard": {
        "max_income": 58200,
        "source_note": "North Carolina’s 2026 application materials show the Circuit Breaker limit at 150% of the income eligibility limit, which is $58,200 for 2026."
      },
      "tiers": [
        {
          "income_at_or_below": 38800,
          "property_tax_cap": "4% of the owner’s income"
        },
        {
          "income_above": 38800,
          "income_at_or_below": 58200,
          "property_tax_cap": "5% of the owner’s income"
        }
      ],
      "notes": [
        "Some county pages and older state documents show prior-year figures that differ from the 2026 statewide amount.",
        "For this program, the relevant rule is the current tax year’s statewide income threshold used by the county tax assessor."
      ]
    },
    "asset_limits": null,
    "other_requirements": [
      "Applicant must be a North Carolina resident.",
      "Applicant must own and occupy the property as a permanent residence.",
      "The property must have been owned and occupied as a permanent residence for at least five consecutive years.",
      "Application must be filed annually.",
      "If there are multiple owners, all owners must qualify; for unmarried joint owners, each owner must apply and qualify separately.",
      "The owner must either be age 65 or older or totally and permanently disabled."
    ]
  },
  "benefits": {
    "type": "financial",
    "value": "Property taxes on the qualifying residence are capped at 4% of income for owners with income at or below $38,800, or 5% of income for owners with income above $38,800 and up to $58,200. Any property taxes above that capped amount are deferred rather than forgiven. Deferred taxes become payable later if a disqualifying event occurs, and the last three years of deferred taxes become payable with interest.",
    "varies_by": "fixed"
  },
  "application": {
    "methods": [
      "Submit Form AV-9 to the county tax assessor where the property is located.",
      "Use the NCDOR property tax forms page to obtain the current AV-9 application.",
      "Contact the county tax office for local filing instructions; some counties accept mail and provide local phone assistance."
    ],
    "processing_time": "No statewide processing-time standard was identified in the available materials. Applications are annual and generally tied to the June 1 filing deadline.",
    "waitlist": null,
    "forms": [
      "AV-9, Application for Property Tax Relief"
    ],
    "documents": [
      "Federal income tax return for the previous year",
      "Social Security benefits statement (1099 or equivalent)",
      "Proof of ownership and occupancy may be requested by the county tax office",
      "Information on all property owners if there are multiple owners",
      "Any disability documentation if qualifying through disability rather than age"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Available statewide in North Carolina through county tax assessors; no county-only restriction was identified.",
    "regional_variations": "The program rules are statewide, but counties may differ in how they administer intake, answer questions, and remind residents of deadlines. County websites may publish local contact numbers, mailing addresses, and brochures, and some counties show older local summaries with outdated threshold figures.",
    "offices_or_providers": [
      "County tax assessor / county tax office where the property is located",
      "North Carolina Department of Revenue property tax forms page"
    ]
  },
  "official_source": "https://www.ncdor.gov/taxes-forms/property-tax/property-tax-forms",
  "gotchas": [
    "This is not a cash benefit; it is a tax deferral. The deferred tax is still owed later if a disqualifying event happens.",
    "The last three years of deferred taxes become payable with interest after a disqualifying event.",
    "You must reapply every year; approval is not automatic.",
    "All owners must qualify, which is easy to miss when a home is jointly owned.",
    "The five-year ownership-and-occupancy rule is separate from the age or disability rule.",
    "County brochures and older pages may show outdated income limits, so families should rely on the current year’s AV-9 instructions and county assessor guidance."
  ],
  "data_shape_notes": "This program is a statewide property-tax deferral with tiered income-based caps, annual reapplication, and a five-year ownership/occupancy requirement; the benefit is deferred taxes, not a service package or grant."
}
